public static Node<Integer> buildDigit(Node<Integer> lst) {
    Node<Integer> dummy = new Node<Integer>(0);   // חוליה זמנית בתחילת השרשרת החדשה
    Node<Integer> last = dummy;
    Node<Integer> p = lst;
    while (p != null) {
        int num = p.getValue();
        while (num > 0) {
            last.setNext(new Node<Integer>(num % 10));   // ספרת האחדות של num
            last = last.getNext();
            num = num / 10;
        }
        last.setNext(new Node<Integer>(-9));   // סוף המספר
        last = last.getNext();
        p = p.getNext();
    }
    return dummy.getNext();
}

