public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

public static Node<Integer> build(int[] values) {
    Node<Integer> first = null;
    for (int i = values.length - 1; i >= 0; i--) {
        first = new Node<Integer>(values[i], first);
    }
    return first;
}

