            last.SetNext(new Node<int>(num % 10));   // ספרת האחדות של num
            last = last.GetNext();
            num = num / 10;
        }
        last.SetNext(new Node<int>(-9));   // סוף המספר
        last = last.GetNext();
        p = p.GetNext();
    }
    return dummy.GetNext();
}

